describe('ChatOrchestrator onError Error identity', () => {
  it('passes an existing Error instance through to onError', async () => {
    const reason = new Error('already an Error');
    const provider: AIProvider = {
      // eslint-disable-next-line require-yield
      async *sendMessage(): AsyncGenerator<MessageChunk> {
        throw reason;
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
    let received: Error | undefined;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        received = error;
      },
    };
    const orchestrator = createChatOrchestrator(
      provider,
      new PromptBuilder({identity: 'You are a test assistant.'}),
      undefined,
      {hooks}
    );

    await expect(orchestrator.processMessage(session)).rejects.toBe(reason);

    expect(received).toBe(reason);
  });
});

